 def velocities(index):
  return dict(forward_m_s=float(velocity[index,:2]@axis),lateral_m_s=float(velocity[index,:2]@side),vertical_m_s=float(velocity[index,2]),speed_m_s=float(np.linalg.norm(velocity[index])))
 def relative_state(index):
  delta=position[index,:2]-bucket_xy
  return dict(longitudinal_relative_bucket_mm=float(delta@axis*1000),lateral_relative_bucket_mm=float(delta@side*1000),radial_distance_mm=float(np.linalg.norm(delta)*1000),center_height_over_rim_mm=float((position[index,2]-rim)*1000),ball_bottom_height_over_rim_mm=float((position[index,2]-radius-rim)*1000),velocity=velocities(index))
 result=dict(available=True,rebound_state_index=start,rebound_time_s=float(times[start]),outgoing_velocity=velocities(start),first_bucket_force_interval=hit)
 stop=min(int(score_stop),len(force));events={}
 for k,name in enumerate(names):
  active=np.flatnonzero(force[:stop,k]>.01)
  events[name]=dict(active_force_intervals=int(len(active)),first_active_time_s=float(times[active[0]]) if len(active) else None)
