  result.update(first_bucket_contact_time_s=float(times[hit]),first_bucket_force_N=float(force[hit,1]),first_bucket_channels=[names[i] for i in np.flatnonzero(force[hit]>.01)],pre_contact=relative_state(hit),post_first_interval=relative_state(hit+1),after20ms=relative_state(after),after20ms_time_s=float(times[after]),rim_band_at_first_contact=bool(max(position[hit,2],position[hit+1,2])+radius>=rim-.002),bucket_force_norm_integral_first20ms_N_s=float((force[hit:end,1]*duration).sum()),peak_bucket_force_first20ms_N=float(force[hit:end,1].max()) if end>hit else None)
 return result
